#include <algorithm>
#include <iostream>
#include <string>

int main(int argc, char **argv) {
    unsigned long long n = std::stoull(argv[1]);
    std::string a = "1";
    std::string b = "1";
    for (unsigned long long i = 0; i < n; ++i) {
        std::string next;
        int ia = static_cast<int>(a.size());
        int ib = static_cast<int>(b.size());
        int carry = 0;
        while (ia > 0 || ib > 0 || carry != 0) {
            int sum = carry;
            if (ia > 0) sum += a[--ia] - '0';
            if (ib > 0) sum += b[--ib] - '0';
            next.push_back(static_cast<char>('0' + sum % 10));
            carry = sum / 10;
        }
        std::reverse(next.begin(), next.end());
        a = b;
        b = next;
    }
    std::cout << a << '\n';
    return 0;
}

