use std::env;
// \
fn main() {
// \
    let n: usize = env::args().nth(1).unwrap().parse().unwrap();
// \
    let mut a = String::from("1");
// \
    let mut b = String::from("1");
// \
    for _ in 0..n {
// \
        let mut digits = Vec::new();
// \
        let mut ia = a.len();
// \
        let mut ib = b.len();
// \
        let mut carry = 0u8;
// \
        while ia > 0 || ib > 0 || carry != 0 {
// \
            let mut sum = carry;
// \
            if ia > 0 { ia -= 1; sum += a.as_bytes()[ia] - b'0'; }
// \
            if ib > 0 { ib -= 1; sum += b.as_bytes()[ib] - b'0'; }
// \
            digits.push(b'0' + sum % 10);
// \
            carry = sum / 10;
// \
        }
// \
        digits.reverse();
// \
        let next = String::from_utf8(digits).unwrap();
// \
        a = b;
// \
        b = next;
// \
    }
// \
    println!("{}", a);
// \
}

